describe('Sticky Footer Navigation on Mobile', () => {
  beforeEach(() => {
    cy.visit('/mobile-page');
  });

  it('should display sticky footer navigation when content is short', () => {
    // Verify page loads in mobile viewport
    cy.viewport('iphone-x');
    cy.get('[data-testid="mobile-page-container"]').should('be.visible');

    // Verify footer is visible and sticky
    cy.get('[data-testid="footer-nav"]').should('be.visible');
    cy.get('[data-testid="footer-nav"]').should('have.css', 'position', 'fixed');

    // Verify footer is at the bottom of the viewport
    cy.get('[data-testid="footer-nav"]').should('have.css', 'bottom', '0px');

    // Verify footer contains navigation links
    cy.get('[data-testid="footer-nav"]').should('contain', 'Home');
    cy.get('[data-testid="footer-nav"]').should('contain', 'Search');
    cy.get('[data-testid="footer-nav"]').should('contain', 'Profile');

    // Verify footer is not pushed down by content
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('have.css', 'padding-bottom', '0px');
  });

  it('should handle long content and keep footer sticky at bottom', () => {
    // Intercept API call for long content
    cy.intercept('GET', '/api/long-content').as('loadLongContent');
    cy.get('[data-testid="load-more-button"]').click();
    cy.wait('@loadLongContent');

    // Verify footer is still visible and sticky
    cy.get('[data-testid="footer-nav"]').should('be.visible');
    cy.get('[data-testid="footer-nav"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="footer-nav"]').should('have.css', 'bottom', '0px');

    // Verify main content is scrollable and footer remains fixed
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('have.css', 'overflow', 'auto');

    // Scroll down to verify footer stays in place
    cy.get('[data-testid="main-content"]').scrollTo('bottom');
    cy.get('[data-testid="footer-nav"]').should('be.visible');
    cy.get('[data-testid="footer-nav"]').should('have.css', 'bottom', '0px');

    // Verify footer is not obscured by content
    cy.get('[data-testid="footer-nav"]').should('not.be.hidden');
  });
});
